def populate_unique_service_slugs(apps, schema_editor):
    Services = apps.get_model('services', 'Services')
    used_slugs = set()

    for service in Services.objects.order_by('services_id'):
        base_slug = slugify(service.services_name or service.services_title or f'service-{service.services_id}') or f'service-{service.services_id}'
        slug = base_slug
        suffix = 1

        while slug in used_slugs or Services.objects.filter(slug=slug).exclude(pk=service.pk).exists():
            suffix_text = f'-{suffix}'
            slug = f'{base_slug[:150 - len(suffix_text)]}{suffix_text}'
            suffix += 1

        used_slugs.add(slug)
        service.slug = slug
        service.save(update_fields=['slug'])


